do $$declare u uuid:='96000000-0000-0000-0000-000000000001';sid uuid;nid uuid;did uuid;n bigint;r record;begin
 insert into auth.users(id,email)values(u,'push-user@x.iq');perform set_config('role','authenticated',false);perform set_config('request.jwt.claim.sub',u::text,false);sid:=public.notification_register_push('https://push.example.test/subscription/1234567890',repeat('a',65),repeat('b',24),null,'Test Browser','android','جهاز الاختبار');perform public.notification_update_preferences(true,true,true,false,null,null);
 execute'reset role';insert into public.notifications(user_id,title,body,type,category,priority,link)values(u,'تنبيه Push','اختبار التسليم','warning','departure','critical','/manager/vehicle-trips')returning id into nid;select count(*)into n from public.notification_push_deliveries where notification_id=nid and subscription_id=sid and status='pending';if n<>1 then raise exception'PUSH_QUEUE_FAIL';end if;
 perform set_config('role','service_role',false);perform set_config('request.jwt.claims','{"role":"service_role"}',false);select*into r from public.notification_claim_push(10,null)where subscription_id=sid;if r.delivery_id is null then raise exception'PUSH_CLAIM_FAIL';end if;did:=r.delivery_id;perform public.notification_finish_push(did,false,410,'expired',true);select count(*)into n from public.notification_push_subscriptions where id=sid and not is_active and failure_count=1;if n<>1 then raise exception'PUSH_PERMANENT_FAILURE_FAIL';end if;select count(*)into n from public.notification_push_deliveries where id=did and status='failed';if n<>1 then raise exception'PUSH_DELIVERY_FINAL_STATUS_FAIL';end if;
 execute'reset role';perform set_config('role','authenticated',false);perform set_config('request.jwt.claim.sub',u::text,false);select count(*)into n from public.notification_push_devices()where id=sid and not is_active;if n<>1 then raise exception'PUSH_DEVICE_LIST_FAIL';end if;
 raise notice'✅ Web Push: التسجيل/الطابور/المطالبة/فشل 410/تعطيل الجهاز/العزل ناجحة';end$$;
